  async function waitMail(afterCount=0) {
    for(let i=0;i<100;i++) {
      const files=await readdir(join(directory,'mail')).catch(()=>[]);
      if(files.length>afterCount)return JSON.parse(await readFile(join(directory,'mail',files.sort().at(-1)),'utf8'));
      await new Promise(resolve=>setTimeout(resolve,20));
    }
    throw new Error('E-mail local absent.');
  }
